func TestListCommand_ShowsUnreadMessages(t *testing.T) {
	db := testutil.NewTestDB(t)

	// Insert 2 messages for agent "mike"
	msg1 := inbox.Message{From: "alice", To: "mike", Subject: "Msg 1", Archived: false}
	msg2 := inbox.Message{From: "bob", To: "mike", Subject: "Msg 2", Archived: false}
	msg3 := inbox.Message{From: "charlie", To: "mike", Subject: "Archived Msg", Archived: true}
	msg4 := inbox.Message{From: "dave", To: "someone-else", Subject: "Other Agent", Archived: false}

	db.Create(&msg1)
	db.Create(&msg2)
	db.Create(&msg3)
	db.Create(&msg4)

	// Capture stdout
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	args := []string{"list", "--agent", "mike"}
	err := run(args, db)
	if err != nil {
		t.Fatalf("run() failed: %v", err)
	}

	w.Close()
	os.Stdout = oldStdout

	var buf bytes.Buffer
	_, _ = io.Copy(&buf, r)
	output := buf.String()

	// Verify both unread messages for mike appear
	if !contains(output, msg1.Subject) {
		t.Errorf("expected output to contain %q, got %q", msg1.Subject, output)
	}
	if !contains(output, msg2.Subject) {
		t.Errorf("expected output to contain %q, got %q", msg2.Subject, output)
	}
	if contains(output, msg3.Subject) {
		t.Errorf("expected output NOT to contain archived message %q", msg3.Subject)
	}
	if contains(output, msg4.Subject) {
		t.Errorf("expected output NOT to contain message for other agent %q", msg4.Subject)
	}
}

func TestArchiveCommand_ArchivesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)

	msg := inbox.Message{From: "alice", To: "bob", Subject: "Archive Me", Archived: false}
