	args := []string{"archive", "--id", msg.ID}
	err := run(args, db)
	if err != nil {
		t.Fatalf("run() failed: %v", err)
	}

	var updatedMsg inbox.Message
	db.First(&updatedMsg, "id = ?", msg.ID)
	if !updatedMsg.Archived {
		t.Error("expected message to be archived")
	}
